def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings."""
    # Simple approach: find first position where characters differ
    for i, (c_in, c_out) in enumerate(zip(s_in, s_out)):
        if c_in != c_out:
            # For simplicity, we'll assume single character replacement
            return (c_in, c_out, i)

    # If strings are of different length or we're at end of shorter string
    if len(s_in) > len(s_out):
        return (s_in[len(s_out)], '', len(s_out))
    elif len(s_out) > len(s_in):
        return ('', s_out[len(s_in)], len(s_in))
    else:
        return ('', '', -1)  # No difference found

# Analyze the changed pairs
changed = [(0, 'awhw', 'awaw'), (1, 'ugzv', 'ugzg')]

for idx, s_in, s_out in changed:
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    print(f"Pair {idx}: '{s_in}' -> '{s_out}' | Change: '{old_sub}' -> '{new_sub}' at position {pos}")

